#include <algorithm>
namespace nagaplas::transactions{CommandDispatcher::CommandDispatcher(size_t n):limit_(std::max<size_t>(1,n)){}uint64_t CommandDispatcher::hash(const std::string&s)noexcept{uint64_t h=14695981039346656037ull;for(unsigned char c:s){h^=c;h*=1099511628211ull;}return h;}CommandResult CommandDispatcher::dispatch(const std::string&p,const std::string&r,const std::string&d,const ApplyCommand&fn,uint64_t exp){std::lock_guard l(m_);if(p.empty()||r.empty()||!fn)return{ResultCode::InvalidRequest,false,rev_,state_,"missing identifiers/callback"};auto&q=cache_[p];auto h=hash(d);auto it=std::find_if(q.begin(),q.end(),[&](auto&x){return x.id==r;});if(it!=q.end()){if(it->hash!=h)return{ResultCode::IdempotencyConflict,false,rev_,state_,"payload differs"};auto x=it->result;x.code=ResultCode::Duplicate;x.is_duplicate=true;return x;}if(exp!=UINT64_MAX&&exp!=rev_)return{ResultCode::RevisionMismatch,false,rev_,state_,"revision mismatch"};if(rev_==UINT64_MAX)return{ResultCode::ApplyFailed,false,rev_,state_,"revision overflow"};std::string next;bool ok=false;try{ok=fn(state_,d,next);}catch(...){ok=false;}if(!ok)return{ResultCode::ApplyFailed,false,rev_,state_,"command failed"};state_=std::move(next);++rev_;CommandResult out{ResultCode::Applied,false,rev_,state_,"committed"};q.push_back({r,h,out});while(q.size()>limit_)q.pop_front();return out;}uint64_t CommandDispatcher::revision()const{std::lock_guard l(m_);return rev_;}std::string CommandDispatcher::state()const{std::lock_guard l(m_);return state_;}void CommandDispatcher::reset(std::string s){std::lock_guard l(m_);rev_=0;state_=std::move(s);cache_.clear();}}